parameters.functionCode:
const crypto = require('crypto');
const ticketId = crypto.randomBytes(16).toString('hex');
const qrData = `EVENT:{{ $('Webhook - Attendee Registration').item.json.event_id }}|ATTENDEE:{{ $json.attendee_email }}|TICKET:${ticketId}`;
return {json: {...$json, ticket_id: ticketId, qr_data: qrData}};

parameters.message:
=Thank you for registering!

Your ticket ID: {{ $json.ticket_id }}

Please present the QR code at the entrance.
